insert into public.brand_sections (client_id,section,content) values ('338df280-25b0-0736-1b34-299128d4e0bc','overview','{"name":"Kestrel Outdoor","tagline":"Made for what comes next.","description":"Kestrel Outdoor creates considered experiences with a clear point of view.","audience":"Curious people who value purposeful design.","tone":["Clear","Confident","Human"],"rules":["Keep the message direct.","Use generous whitespace.","Build on the core brand palette."]}');
