insert into public.brand_sections (client_id,section,content) values ('ea650ad5-f8e2-8a3c-5012-bf0d69df498e','overview','{"name":"Pelagic","tagline":"Made for what comes next.","description":"Pelagic creates considered experiences with a clear point of view.","audience":"Curious people who value purposeful design.","tone":["Clear","Confident","Human"],"rules":["Keep the message direct.","Use generous whitespace.","Build on the core brand palette."]}');
insert into public.brand_sections (client_id,section,content) values ('ea650ad5-f8e2-8a3c-5012-bf0d69df498e','logos','{"guidance":"Maintain clear space equal to the height of the wordmark.","variants":["Primary wordmark","Compact mark","Reversed wordmark"]}');
insert into public.brand_sections (client_id,section,content) values ('ea650ad5-f8e2-8a3c-5012-bf0d69df498e','colors','{"palette":[{"name":"Ink","hex":"#191919"},{"name":"Paper","hex":"#F7F6F2"},{"name":"Stone","hex":"#C9C5BB"},{"name":"Accent","hex":"#D4DCB4"}]}');
